        if(v.is_int()) {
            const auto n=integer(v,work);std::array<char,32> b{};const auto [e,ec]=std::to_chars(b.data(),b.data()+b.size(),n);
            need(ec==std::errc{},"protocol: ER107 integer encoding");return static_cast<std::size_t>(e-b.data());
        }
