            case '"':put(out,"\\\"");break;case '\\':put(out,"\\\\");break;
            case '\b':put(out,"\\b");break;case '\f':put(out,"\\f");break;
            case '\n':put(out,"\\n");break;case '\r':put(out,"\\r");break;case '\t':put(out,"\\t");break;
            default:if(c<32){const std::array<char,6> esc{'\\','u','0','0',hex[c>>4],hex[c&15]};put(out,{esc.data(),esc.size()});}
                else {const char byte=static_cast<char>(c);put(out,{&byte,1});}
