// Hash the complete documented array preimage. Each wrapper is sorted by key,
// notably manifest_record precedes path; no metadata subset is substituted.
inline void full_component_array(JsonVal cases,std::string_view value_key,std::string_view expected,OracleWork& work) {
    pay(work,kMaxFactBytes,2,128);std::string preimage;preimage.reserve(kMaxFactBytes);
    const auto append=[&](std::string_view bytes) {
        need(bytes.size()<=kMaxFactBytes-preimage.size(),"resource: ER107 component array byte bound");pay(work,bytes.size(),1);preimage.append(bytes);
    };
    append("[");
    for(std::size_t i=0;i<cases.size();++i) {
        const auto row=at(cases,i,work);const auto path=canonical(get(row,"path",work),work),value=canonical(get(row,value_key,work),work);
        if(i)append(",");append("{");
        const auto field=[&](std::string_view name,std::string_view encoded) {append("\"");append(name);append("\":");append(encoded);};
        if(value_key<"path"){field(value_key,value);append(",");field("path",path);}
        else {field("path",path);append(",");field(value_key,value);}
        append("}");
    }
    append("]");need(digest(preimage,work)==expected,"source: ER107 full component array digest");
}
