    same_text(get(source,"schema",work),"loom_er107_complete_source_proposal/v1",work,"protocol: ER107 root schema");
    same_text(get(source,"review_status",work),"UNREVIEWED",work,"source: ER107 frozen asset status unchanged by source review");
    const auto qualification=get(source,"qualification",work);
    zero(get(qualification,"drawing_credit",work),work);zero(get(qualification,"upstream_assertion_credit",work),work);zero(get(qualification,"originals_added",work),work);null_terminal(qualification,"terminal_model",work);
